from pathlib import Path, PurePosixPath

from sort_pilot.classification import Template
from sort_pilot.curriculum import StudentType, load_subject_catalog


REAL_DATASET_VERSION = "real-student-pdf-v1"
SUPPORTED_REAL_SUFFIXES = frozenset({".pdf"})
REVIEW_STATES = frozenset({"pending", "confirmed", "excluded"})
EXTRACTION_STATES = frozenset({"not_run", "ready", "text_poor", "failed", "unsupported"})
BLOCKED_SUFFIXES = frozenset({
    ".lnk", ".url", ".exe", ".msi", ".bat", ".cmd", ".com", ".scr", ".ps1",
})
TEMP_SUFFIXES = frozenset({".tmp", ".part", ".crdownload", ".download"})


def _required_text(value: object, field: str) -> str:
    """Validate and normalize one required manifest text field."""
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field} must be nonblank text")
    return value.strip()


def _optional_text(value: object, field: str) -> str | None:
    """Validate optional manifest text without coercing other types."""
    if value is None:
        return None
    return _required_text(value, field)


@dataclass(frozen=True, slots=True)
class RealDatasetRecord:
    """One private local file plus draft and human-confirmed bounded labels."""

    record_id: str
    relative_path: str
    sha256: str
    byte_size: int
    suffix: str
    student_type: str
    group_id: str
    extraction_status: str
    review_status: str
    draft_subject: str | None = None
    draft_template: str | None = None
    draft_subject_score: float | None = None
    draft_subject_margin: float | None = None
    draft_template_score: float | None = None
    draft_template_margin: float | None = None
    subject: str | None = None
    template: str | None = None
    review_note: str = ""

    def __post_init__(self) -> None:
        """Validate identity, path bounds, states, and catalog labels."""
        record_id = _required_text(self.record_id, "record_id")
        relative = _required_text(self.relative_path, "relative_path").replace("\\", "/")
        relative_parts = PurePosixPath(relative).parts
        if PurePosixPath(relative).is_absolute() or ".." in relative_parts:
            raise ValueError("relative_path must stay inside the selected dataset root")
        sha256 = _required_text(self.sha256, "sha256").lower()
        if len(sha256) != 64 or any(char not in "0123456789abcdef" for char in sha256):
            raise ValueError("sha256 must contain exactly 64 hexadecimal characters")
        if record_id != hashlib.sha256(f"{relative}\0{sha256}".encode("utf-8")).hexdigest():
            raise ValueError("record_id does not match the relative path and content hash")
        if type(self.byte_size) is not int or self.byte_size < 0:
            raise ValueError("byte_size must be a nonnegative integer")
        suffix = _required_text(self.suffix, "suffix").casefold()
        student_type = StudentType(_required_text(self.student_type, "student_type"))
        group_id = _required_text(self.group_id, "group_id")
        if self.extraction_status not in EXTRACTION_STATES:
            raise ValueError("unsupported extraction_status")
        if self.review_status not in REVIEW_STATES:
            raise ValueError("unsupported review_status")
        if suffix not in SUPPORTED_REAL_SUFFIXES:
            if self.review_status != "excluded" or self.extraction_status != "unsupported":
                raise ValueError("unsupported formats must remain explicit exclusions")
        elif self.review_status == "excluded":
            raise ValueError("supported PDFs cannot be silently excluded")

        allowed_subjects = set(load_subject_catalog().subjects_for(student_type))
        allowed_templates = {item.value for item in Template}
        for value, field, allowed in (
            (self.draft_subject, "draft_subject", allowed_subjects),
            (self.subject, "subject", allowed_subjects),
            (self.draft_template, "draft_template", allowed_templates),
            (self.template, "template", allowed_templates),
        ):
            parsed = _optional_text(value, field)
            if parsed is not None and parsed not in allowed:
                raise ValueError(f"{field} is outside the fixed classifier catalog")
            object.__setattr__(self, field, parsed)
        for value, field in (
            (self.draft_subject_score, "draft_subject_score"),
            (self.draft_subject_margin, "draft_subject_margin"),
            (self.draft_template_score, "draft_template_score"),
            (self.draft_template_margin, "draft_template_margin"),
        ):
            if value is not None and (isinstance(value, bool) or not isinstance(value, (int, float))):
                raise ValueError(f"{field} must be numeric or null")
        if self.review_status == "confirmed" and (self.subject is None or self.template is None):
            raise ValueError("confirmed records require both human labels")
        if self.review_status == "pending" and (self.subject is not None or self.template is not None):
            raise ValueError("pending records cannot contain human-confirmed labels")
        if not isinstance(self.review_note, str):
            raise ValueError("review_note must be text")

        object.__setattr__(self, "record_id", record_id)
        object.__setattr__(self, "relative_path", relative)
        object.__setattr__(self, "sha256", sha256)
        object.__setattr__(self, "suffix", suffix)
        object.__setattr__(self, "student_type", student_type.value)
        object.__setattr__(self, "group_id", group_id)
        object.__setattr__(self, "review_note", self.review_note.strip())

    @property
    def supported(self) -> bool:
        """Return whether this iteration can extract and evaluate the file."""
        return self.suffix in SUPPORTED_REAL_SUFFIXES

    def with_draft(
        self,
        *,
        subject: str,
        template: str,
        subject_score: float,
        subject_margin: float,
        template_score: float,
        template_margin: float,
        extraction_status: str,
    ) -> "RealDatasetRecord":
        """Attach non-authoritative local classifier draft labels."""
        return replace(
            self,
            draft_subject=subject,
            draft_template=template,
            draft_subject_score=float(subject_score),
            draft_subject_margin=float(subject_margin),
            draft_template_score=float(template_score),
            draft_template_margin=float(template_margin),
            extraction_status=extraction_status,
        )

    def confirm(self, subject: str, template: str, note: str = "") -> "RealDatasetRecord":
        """Return a human-confirmed record with both fixed axes selected."""
        return replace(
            self,
            review_status="confirmed",
            subject=subject,
            template=template,
            review_note=note,
        )

    def to_dict(self) -> dict:
        """Serialize private metadata and labels without extracted text."""
        return {
            field: getattr(self, field)
            for field in self.__dataclass_fields__
        }

    @classmethod
    def from_dict(cls, value: object) -> "RealDatasetRecord":
        """Parse one strict private record document."""
        if not isinstance(value, dict) or set(value) != set(cls.__dataclass_fields__):
            raise ValueError("real dataset record fields are invalid")
        return cls(**value)


@dataclass(frozen=True, slots=True)
class RealDatasetManifest:
    """Strict private manifest containing no extracted document text."""

    dataset_name: str
    records: tuple[RealDatasetRecord, ...]
    version: str = REAL_DATASET_VERSION

    def __post_init__(self) -> None:
        """Validate manifest version and unique record identities."""
        if self.version != REAL_DATASET_VERSION:
            raise ValueError("unsupported real dataset manifest version")
        object.__setattr__(self, "dataset_name", _required_text(self.dataset_name, "dataset_name"))
        if not isinstance(self.records, tuple) or not self.records:
            raise ValueError("a real dataset manifest requires records")
        if not all(isinstance(record, RealDatasetRecord) for record in self.records):
            raise ValueError("manifest records are invalid")
        record_ids = [record.record_id for record in self.records]
        relative_paths = [record.relative_path.casefold() for record in self.records]
        if len(record_ids) != len(set(record_ids)) or len(relative_paths) != len(set(relative_paths)):
            raise ValueError("manifest records must have unique identities and paths")

    @property
    def supported_records(self) -> tuple[RealDatasetRecord, ...]:
        """Return the PDF records eligible for this experiment."""
        return tuple(record for record in self.records if record.supported)

    @property
    def confirmed_records(self) -> tuple[RealDatasetRecord, ...]:
        """Return only supported records whose two labels were confirmed."""
        return tuple(record for record in self.supported_records if record.review_status == "confirmed")

    @property
    def ready_for_evaluation(self) -> bool:
        """Require human confirmation for every supported record."""
        return bool(self.supported_records) and len(self.confirmed_records) == len(self.supported_records)

    def replace_record(self, updated: RealDatasetRecord) -> "RealDatasetManifest":
        """Immutably replace one existing record by stable identity."""
        if updated.record_id not in {record.record_id for record in self.records}:
            raise ValueError("updated record is not part of this manifest")
        return replace(
            self,
            records=tuple(updated if record.record_id == updated.record_id else record for record in self.records),
        )

    def to_dict(self) -> dict:
        """Serialize one strict private manifest document."""
        return {
            "version": self.version,
            "dataset_name": self.dataset_name,
            "records": [record.to_dict() for record in self.records],
        }

    @classmethod
    def from_dict(cls, value: object) -> "RealDatasetManifest":
        """Parse one strict private manifest document."""
        if not isinstance(value, dict) or set(value) != {"version", "dataset_name", "records"}:
            raise ValueError("real dataset manifest fields are invalid")
        records = value["records"]
        if not isinstance(records, list):
            raise ValueError("manifest records must be a list")
        return cls(
            version=value["version"],
            dataset_name=value["dataset_name"],
            records=tuple(RealDatasetRecord.from_dict(record) for record in records),
        )


def _file_sha256(path: Path) -> str:
    """Stream one local file into a stable content digest."""
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _safe_files(root: Path) -> tuple[Path, ...]:
    """Collect bounded non-link, non-executable dataset files recursively."""
    resolved_root = root.resolve(strict=True)
    if not resolved_root.is_dir():
        raise ValueError("dataset root must be a directory")
    files: list[Path] = []
    for path in resolved_root.rglob("*"):
        if path.is_symlink() or not path.is_file() or path.name.startswith((".", "~$", "~")):
            continue
        suffix = path.suffix.casefold()
        if suffix in BLOCKED_SUFFIXES or suffix in TEMP_SUFFIXES:
            continue
        resolved = path.resolve(strict=True)
        if not resolved.is_relative_to(resolved_root):
            continue
        files.append(resolved)
    return tuple(sorted(files, key=lambda path: path.relative_to(resolved_root).as_posix().casefold()))


def scan_real_dataset(
    root: Path,
    *,
    student_type: StudentType,
    existing: RealDatasetManifest | None = None,
) -> RealDatasetManifest:
    """Inventory a local dataset without reading or persisting document text."""
    resolved_root = root.resolve(strict=True)
    existing_by_identity = {
        (record.relative_path, record.sha256): record
        for record in existing.records
    } if existing is not None else {}
    records: list[RealDatasetRecord] = []
    for path in _safe_files(resolved_root):
        relative = path.relative_to(resolved_root).as_posix()
        sha256 = _file_sha256(path)
        previous = existing_by_identity.get((relative, sha256))
        if previous is not None:
            records.append(previous)
            continue
        record_id = hashlib.sha256(f"{relative}\0{sha256}".encode("utf-8")).hexdigest()
        suffix = path.suffix.casefold() or "<none>"
        supported = suffix in SUPPORTED_REAL_SUFFIXES
        records.append(
            RealDatasetRecord(
                record_id=record_id,
                relative_path=relative,
                sha256=sha256,
                byte_size=path.stat().st_size,
                suffix=suffix,
                student_type=student_type.value,
                group_id=f"sha256:{sha256}",
                extraction_status="not_run" if supported else "unsupported",
                review_status="pending" if supported else "excluded",
            )
        )
    return RealDatasetManifest(dataset_name=resolved_root.name, records=tuple(records))


def source_path(root: Path, record: RealDatasetRecord) -> Path:
    """Resolve and revalidate one manifest path beneath its selected source root."""
    resolved_root = root.resolve(strict=True)
    candidate = (resolved_root / Path(record.relative_path)).resolve(strict=True)
    if not candidate.is_relative_to(resolved_root) or not candidate.is_file():
        raise ValueError("manifest source escaped or disappeared from the dataset root")
    if _file_sha256(candidate) != record.sha256:
        raise ValueError("manifest source content changed after inventory")
    return candidate


def load_real_manifest(path: Path) -> RealDatasetManifest:
    """Strictly load one private local evaluation manifest."""
    try:
        return RealDatasetManifest.from_dict(json.loads(path.read_text(encoding="utf-8")))
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise RuntimeError(f"cannot load private real-data manifest: {path}") from exc


def save_real_manifest(path: Path, manifest: RealDatasetManifest) -> None:
    """Atomically save private labels inside the caller-selected ignored directory."""
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(manifest.to_dict(), ensure_ascii=False, indent=2) + "\n"
    descriptor, temporary_name = tempfile.mkstemp(
        prefix=f".{path.name}.", suffix=".tmp", dir=path.parent
    )
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)

