  @{ Path='C:\Users\nobody haha\Downloads\total_labels.csv'; Subject='과목' },
  @{ Path='C:\Users\nobody haha\Downloads\200개\새 폴더\분류_레이블.csv'; Subject='과목' },
  @{ Path='C:\Users\nobody haha\Downloads\data\라벨데이터_최종_102개\labels.csv'; Subject='과목' }
)
foreach ($config in $configs) {
  $rows = @(Import-Csv -Encoding UTF8 -LiteralPath $config.Path)
  "===== $($config.Path) ====="
  $rows | Group-Object -Property $config.Subject | Sort-Object Name | ForEach-Object {
    $display = if ([string]::IsNullOrWhiteSpace($_.Name)) { '<blank>' } else { $_.Name }
    "SUBJECT=$display|COUNT=$($_.Count)"
  }
}

